// Source of the Vercel Functions api/events.js and api/types.js (generated by `npm run bundle:api`).
// Vercel does not reliably resolve this repo's relative `.ts` imports at runtime, so the functions are
// shipped as one self-contained file each, like Lattice's own api/proxy.ts. The key comes from Vercel
// environment variables and never reaches the browser.
import {createApiHandler} from './handler.ts';

const handle = createApiHandler();

export default {
  fetch: (request: Request): Promise<Response> => handle(request),
};
